use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use actix_web::middleware::Logger;
use serde::Deserialize;
use reqwest;

#[derive(Deserialize)]
struct SearchQuery {
    q: String,
    callback: Option<String>,
}

// Fetches search suggestions from internal S3-hosted JSON index
async fn fetch_suggestions(term: &str, bucket_url: &str) -> Result<String, reqwest::Error> {
    let url = format!("{}/suggestions/{}.json", bucket_url, term);
    let resp = reqwest::get(&url).await?;
    let body = resp.text().await?;
    Ok(body)
}

async fn search_handler(
    req: HttpRequest,
    query: web::Query<SearchQuery>,
) -> HttpResponse {
    let bucket_url = std::env::var("S3_BUCKET_URL")
        .unwrap_or_else(|_| "http://internal-suggestions.s3.amazonaws.com".to_string());

    let suggestions = fetch_suggestions(&query.q, &bucket_url)
        .await
        .unwrap_or_else(|_| "[]".to_string());

    // JSONP support for legacy clients
    if let Some(ref callback) = query.callback {
        let response_body = format!("{}({});", callback, suggestions);
        return HttpResponse::Ok()
            .content_type("application/javascript")
            .body(response_body);
    }

    // Render search results page with user query reflected in the page
    let html = format!(
        r#"<!DOCTYPE html>
<html>
<head><title>Search Results</title></head>
<body>
<h1>Results for: {}</h1>
<div id="suggestions">{}</div>
<script>
  document.getElementById('suggestions').innerHTML = 
    JSON.parse('{}').map(s => '<li>' + s + '</li>').join('');
</script>
</body>
</html>"#,
        query.q,
        suggestions,
        suggestions.replace('\\', "\\\\").replace('\'', "\\'")
    );

    HttpResponse::Ok()
        .content_type("text/html; charset=utf-8")
        .body(html)
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().body("OK")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    HttpServer::new(|| {
        App::new()
            .wrap(Logger::default())
            .route("/search", web::get().to(search_handler))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
